package org.memphiszoo.custodial.vault;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.JSONObject;class CustodialNativeRuntime {static CustodialNativeRuntime instance;volatile NativeProviderPrincipal principal=new NativeProviderPrincipal("A");volatile boolean unreadable;final Engine engine=new Engine();static CustodialNativeRuntime get(Object c){return instance;}NativeProviderPrincipal readProviderPrincipal()throws VaultFailure {if(unreadable)throw new VaultFailure("unreadable");return principal;}interface ResponseHook {AuthorizedResponse answer(AuthorizedRequest r)throws Exception;}static class Engine {final List<AuthorizedRequest> requests=Collections.synchronizedList(new ArrayList<>());volatile ResponseHook hook;AuthorizedResponse authorizedRequest(String device,AuthorizedRequest r)throws Exception {requests.add(r);ResponseHook h=hook;return h==null?success(r):h.answer(r);}static AuthorizedResponse success(AuthorizedRequest r){JSONObject body=new JSONObject(new String(r.body,StandardCharsets.UTF_8));return new AuthorizedResponse(200,new JSONObject().put("ok",true).put("data",new JSONObject().put("sample_id",body.getString("sample_id"))).toString().getBytes(StandardCharsets.UTF_8));}}}
